<template><div class="page"><header class="page-header"><div><p class="eyebrow">Sales channels</p><h1 class="page-title">Listings</h1><p class="page-subtitle">Track where your parts are listed and what each sale returns.</p></div><button class="btn btn-primary" @click="showModal=true"><AppIcon name="plus"/>Add listing</button></header><section class="panel table-panel"><div class="toolbar"><span class="record-count">{{ listings.length }} {{ listings.length===1?'listing':'listings' }}</span></div><div v-if="loading" class="loading-state"><span class="loader"></span></div><div v-else-if="listings.length" class="table-wrap"><table class="data-table"><thead><tr><th>Listing</th><th>Platform</th><th>Price</th><th>Net after fees</th><th>Status</th><th>Listed</th><th></th></tr></thead><tbody><tr v-for="l in listings" :key="l.id"><td><div class="primary-cell">{{ l.external_id }}</div><div class="secondary-cell">Part #{{ l.part_id }}</div></td><td>{{ pretty(l.platform) }}</td><td class="money">{{ money(l.price_c) }}</td><td class="money">{{ money(Number(l.price_c)-Number(l.fees_c)) }}</td><td><span class="status" :class="l.status==='SOLD'?'status-green':'status-amber'">{{ pretty(l.status) }}</span></td><td>{{ date(l.listed_datetime) }}</td><td><a class="btn btn-ghost btn-sm" :href="l.url" target="_blank" rel="noopener">Open <AppIcon name="external"/></a></td></tr></tbody></table></div><div v-else class="empty-state"><span class="empty-icon"><AppIcon name="tag"/></span><h3>No listings yet</h3><p>Add a marketplace listing to start tracking sales.</p></div></section>
<div v-if="showModal" class="modal-backdrop-custom" @click.self="closeModal"><form class="dialog" @submit.prevent="submit"><header class="dialog-header"><div><h2>Add a listing</h2><p>Connect a part to its marketplace listing.</p></div><button type="button" class="icon-button" @click="closeModal"><AppIcon name="close"/></button></header><div class="dialog-body form-grid"><label><span class="form-label">Part ID</span><input v-model.number="form.part_id" type="number" min="1" class="form-control" required></label><label><span class="form-label">Platform</span><select v-model="form.platform" class="form-select"><option>EBAY</option><option>FACEBOOK</option><option>CRAIGSLIST</option></select></label><label><span class="form-label">External ID</span><input v-model="form.external_id" class="form-control" required></label><label><span class="form-label">Status</span><select v-model="form.status" class="form-select"><option>DRAFT</option><option>ACTIVE</option><option>SOLD</option><option>ENDED</option></select></label><label class="field-full"><span class="form-label">Listing URL</span><input v-model="form.url" type="url" class="form-control" placeholder="https://" required></label><label><span class="form-label">Price ($)</span><input v-model.number="form.price_c" type="number" min="0" step=".01" class="form-control" required></label><label><span class="form-label">Fees ($)</span><input v-model.number="form.fees_c" type="number" min="0" step=".01" class="form-control" required></label><label><span class="form-label">Listed date/time</span><input v-model="form.listed_datetime" type="datetime-local" class="form-control"></label><label><span class="form-label">Sold date/time</span><input v-model="form.sold_datetime" type="datetime-local" class="form-control"></label></div><footer class="dialog-footer"><button type="button" class="btn btn-ghost" @click="closeModal">Cancel</button><button class="btn btn-primary">Save listing</button></footer></form></div></div></template>
<script setup>import{ref,onMounted}from'vue';import superagent from'superagent';import{apiUrl}from'../api';import AppIcon from'../components/AppIcon.vue';const listings=ref([]),loading=ref(true),showModal=ref(false);const blank=()=>({part_id:'',platform:'EBAY',external_id:'',url:'',price_c:'',fees_c:'',status:'DRAFT',listed_datetime:'',sold_datetime:''}),form=ref(blank());const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(v||0),pretty=v=>(v||'').replaceAll('_',' ').toLowerCase().replace(/^./,x=>x.toUpperCase()),date=v=>v?new Date(v).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'—';function closeModal(){showModal.value=false;form.value=blank()}async function fetchAll(){loading.value=true;try{const r=await superagent.get(apiUrl('/listings/v1'));listings.value=Array.isArray(r.body)?r.body:[]}catch{listings.value=[]}finally{loading.value=false}}async function submit(){try{const p={...form.value};p.listed_datetime=p.listed_datetime?new Date(p.listed_datetime).toISOString():null;p.sold_datetime=p.sold_datetime?new Date(p.sold_datetime).toISOString():null;await superagent.post(apiUrl('/listings/v1')).send(p);await fetchAll();closeModal()}catch{alert('Unable to add this listing. Please check the details and try again.')}}onMounted(fetchAll)</script>
